/* ================= Akademie, Vertiefung: Aktives Zuhören und Spiegeltechniken ================= */
/* Struktur je Einheit: A Grundlagen, B Psychologie, C Evidenz, D Praxis, E Beispiele, F Grenzen, G Training, Quellen.
   Aussagen in C tragen eine Evidenzstufe und eine Art: beleg (direkt untersucht), transfer (aus anderem Kontext übertragen), heuristik (Erfahrungsregel).
   Neue Einheit: T({...}) aufrufen. Pflichtfelder: id, titel, bereich, stufe, schnell, stand, pruefen. */
var TIEF=[],TIEF_IDX={};
function T(o){o.version=o.version||'1.0';o.stand=o.stand||'2026-10-31';o.pruefen=o.pruefen||'2027-10-31';TIEF.push(o);TIEF_IDX[o.id]=o;return o}
function S(stufe,t,q,art){return {s:stufe,t:t,q:q||[],art:art||'beleg'}}
var TIEF_BEREICHE=[
 ['zuhoeren','Zuhören und Spiegeln','Aktives Zuhören, verbales und nonverbales Spiegeln, sprachliche Anpassung'],
 ['beziehung','Beziehung und Wahrnehmung','Rapport, Vertrauen, erster Eindruck'],
 ['fuehrung','Gesprächsführung','Fragetechniken, Motivational Interviewing, Einwände'],
 ['entscheidung','Entscheidung und Erklärung','Entscheidungspsychologie, verständlich erklären, Verhandlung und Abschluss'],
 ['lernen','Lernen und Training','Wie Gesprächskompetenz wirklich wächst']
];

T({id:'t-zuhoeren',titel:'Aktives Zuhören',bereich:'zuhoeren',haupt:true,stufe:'B',kn:['e1','e2','e3','c8'],verkn:['t-spiegeln','t-paraphrase','t-zusammenfassen','t-emotion','t-rapport','t-mi'],
 schnell:{kern:['Zuhören heißt: aufnehmen, verstehen, zurückmelden. Erst das Zurückmelden macht Verständnis für den Kunden sichtbar.','Kunden fühlen sich durch Zurückmelden eher verstanden als durch schnelle Ratschläge.','Zuhören wirkt vor allem über die Beziehung, weniger direkt auf den Abschluss.','Jede Deutung als Frage formulieren und bestätigen lassen.'],
  satz:'„Wenn ich Sie richtig verstehe, ist Ihnen vor allem wichtig, dass … Stimmt das so?“',vermeiden:['Antwort planen, während der Kunde noch spricht','Zu früh eine Lösung anbieten','Nicken ohne Rückmeldung als Zuhören halten']},
 A:{def:'Aktives Zuhören ist eine Gesprächshaltung und eine Gruppe von Techniken, mit denen ein Zuhörer Aufmerksamkeit zeigt, das Gehörte in eigenen Worten zurückmeldet und so prüft, ob er den Inhalt und die Bedeutung für den Sprecher richtig verstanden hat.',
  herkunft:'Der Begriff geht auf Rogers und Farson (1957) zurück. Er stammt aus der klientenzentrierten Psychologie, in der Rogers Empathie, Echtheit und Wertschätzung als Bedingungen hilfreicher Gespräche beschrieb. Später wurde das Konzept in Führung, Pflege, Pädagogik und Vertrieb übernommen.',
  begriffe:[['Aufmerksamkeit','Nonverbale und verbale Zeichen, dass man beim Gesprächspartner ist.'],['Paraphrase','Wiedergabe des Inhalts in eigenen Worten.'],['Reflexion','Zurückmelden von Gefühl oder Bedeutung hinter einer Aussage.'],['Zusammenfassung','Bündeln mehrerer Aussagen.'],['Verständnisfrage','Prüfen, ob die eigene Deutung stimmt.'],['Wahrgenommenes Zuhören','Wie gut sich der Sprecher gehört fühlt, unabhängig davon, was der Zuhörer tatsächlich tut.']],
  theorie:'Kluger und Itzchakov (2022) beschreiben Zuhören als zweiseitige Episode: Es entsteht zwischen beiden Gesprächspartnern und wird vor allem daran gemessen, wie der Sprecher es erlebt. In der Vertriebsforschung wird aktives, empathisches Zuhören in drei Schritte gegliedert: wahrnehmen, verarbeiten, antworten (Drollinger u. a. 2006).',
  abgrenzung:'Aktives Zuhören ist nicht dasselbe wie Schweigen, Nicken oder Wiederholen. Es unterscheidet sich vom Spiegeln der Körpersprache, das eine eigene, deutlich schwächer belegte Forschungslinie ist. Es ist auch keine Zustimmung: Man kann genau zuhören und trotzdem eine andere fachliche Einschätzung haben.'},
 B:{text:['Wer sich verstanden fühlt, erlebt weniger soziale Bedrohung. Itzchakov u. a. (2017) fanden, dass hochwertiges Zuhören soziale Ängstlichkeit senkt. Sprecher reagierten weniger abwehrend, nahmen eigene Widersprüche bewusster wahr und vertraten weniger extreme Einstellungen.','Das Zurückmelden gibt dem Sprecher die Möglichkeit, Missverständnisse sofort zu korrigieren. Damit wird Zuhören zu einem Mittel der Informationsqualität, nicht nur der Beziehung.','Aufmerksamkeit ist begrenzt. Wer gleichzeitig die eigene Antwort vorbereitet, hört schlechter zu. Bewusstes Zurückmelden zwingt dazu, den Inhalt zu verarbeiten.'],
  alternativ:'Ein Teil der Wirkung kann daran liegen, dass aktives Zuhören einfach mehr Zeit und Freundlichkeit im Gespräch bedeutet. In Studien ist schwer zu trennen, ob die Technik oder die damit verbundene Haltung wirkt.'},
 C:{aussagen:[
   S('B','Menschen fühlen sich nach aktivem Zuhören stärker verstanden als nach Ratschlägen oder bloßer Bestätigung. Bei Zufriedenheit und Sympathie waren die Unterschiede klein.',['weger14'],'beleg'),
   S('C','Die Paraphrase allein verändert vor allem, wie kompetent der Zuhörer wirkt. Ein starker Effekt auf das Verstanden-Fühlen ist für die Paraphrase allein nicht gesichert.',['weger10'],'beleg'),
   S('A','Wahrgenommenes Zuhören hängt im Arbeitskontext deutlich mit Beziehungsqualität zusammen (r̄ = .51) und schwächer mit Leistung (r = .21).',['kluger24'],'beleg'),
   S('B','Im Vertrieb hängen wahrgenommenes Zuhören, Vertrauen und Beziehungsergebnisse zusammen. Die Daten sind überwiegend Befragungen, Ursache und Wirkung sind daher nicht sicher getrennt.',['ramsey97','itani19'],'beleg'),
   S('C','Gutes Zuhören kann Menschen helfen, ihre eigene Abwägung klarer zu sehen. Das ist im Labor gezeigt, nicht in Kaufentscheidungen.',['itz17'],'transfer')],
  widerspruch:'Die Forschung zeigt starke Zusammenhänge, aber viele Studien beruhen auf Selbstauskünften. Experimente zeigen kleinere Effekte als Befragungen. Für den Abschluss selbst ist die direkte Wirkung weniger klar als für Vertrauen und Beziehung.',
  transfer:'Gut untersucht ist Zuhören in Arbeitsbeziehungen und in der Psychotherapie. Für Versicherungsgespräche gibt es wenige direkte Studien. Die Übertragung ist plausibel, weil auch dort Vertrauen und Verstehen zählen, sie ist aber nicht direkt geprüft.'},
 D:{wann:'Immer dann, wenn der Kunde etwas Persönliches, Wichtiges oder Unklares sagt, besonders zu Beginn, bei Sorgen und bei Einwänden.',ziel:'Den Kunden wirklich verstehen und ihm zeigen, dass er verstanden wurde. Daraus entsteht die Grundlage für passende Beratung.',
  schritte:['Ausreden lassen und eine kurze Pause aushalten.','Kernaussage in eigenen Worten zurückmelden.','Wenn ein Gefühl hörbar ist, es vorsichtig benennen.','Mit einer Prüffrage enden: „Habe ich das richtig verstanden?“','Erst danach fragen, wie es weitergehen soll, oder Informationen anbieten.'],
  formulierungen:['„Wenn ich Sie richtig verstehe …“','„Ihnen ist also wichtig, dass …“','„Das klingt, als wäre … für Sie besonders wichtig. Stimmt das?“','„Lassen Sie mich kurz zusammenfassen, was ich bisher verstanden habe.“'],
  reaktion:['Kunde bestätigt: weiter vertiefen („Was genau heißt das für Sie?“).','Kunde korrigiert: dankbar aufnehmen, neu zusammenfassen.','Kunde wirkt genervt: weniger zurückmelden, mehr Raum lassen.'],
  pruefen:'Der Kunde ergänzt Details, korrigiert Missverständnisse, spricht offener. Warnzeichen: einsilbige Antworten, Ungeduld, „Das sagte ich doch schon.“',
  anpassen:'Bei Zeitdruck kürzer zurückmelden. Bei sehr sachlichen Kunden eher Inhalte als Gefühle spiegeln.'},
 E:{gut:'Kunde: „Ich hab schon so viele Versicherungen, ich weiß gar nicht mehr, was ich alles habe.“ Berater: „Sie haben den Überblick über Ihre Verträge ein Stück weit verloren. Wäre es Ihnen eine Hilfe, wenn wir zuerst sortieren, was da ist, bevor wir über Neues sprechen?“',
  schlecht:'Berater: „Das geht vielen so. Ich zeige Ihnen mal unser neues Rundum-Paket.“ (übergeht das Anliegen und springt zum Produkt)',
  dialog:[['K','Meine Mutter ist gerade ins Heim gekommen. Das hat uns alle ziemlich mitgenommen.'],['B','Das klingt nach einer schweren Zeit für Ihre Familie.'],['K','Ja. Und dann die Kosten. Ich hätte nie gedacht, dass das so teuer ist.'],['B','Die Höhe der Kosten hat Sie überrascht. Beschäftigt Sie das eher für Ihre Mutter oder auch mit Blick auf sich selbst?'],['K','Ehrlich gesagt beides.']],
  analyse:'Der Berater meldet zuerst die Belastung zurück, nicht die Kosten. Danach fasst er die Überraschung zusammen und stellt eine offene Unterscheidungsfrage. Er unterstellt nicht, dass der Kunde Pflegevorsorge will.',
  alternative:'Statt einer Frage könnte er auch schweigen und den Kunden weiterreden lassen. Beides ist möglich, wichtig ist, nicht sofort zu den Zahlen zu springen.',
  finanz:'Bei einer Vertragsfälligkeit: „Sie möchten das Geld nicht einfach wieder für zehn Jahre festlegen, weil vielleicht bald eine Renovierung ansteht. Habe ich das richtig verstanden?“',
  allgemein:'Im Autohaus: „Sie suchen etwas Zuverlässiges für den Arbeitsweg, und Komfort ist Ihnen weniger wichtig als niedrige Unterhaltskosten. Stimmt das?“'},
 F:{nicht:['Wenn der Kunde eine kurze Sachauskunft will und Zurückmelden ihn aufhält.','Wenn Zurückmelden nur noch Formel ist und jede Aussage wiederholt wird.'],
  manipulativ:'Wenn Zuhören nur dazu dient, Ansatzpunkte für den Verkauf zu sammeln, und die Rückmeldung nicht ehrlich gemeint ist. Kunden erkennen solche Taktiken häufig (Friestad und Wright 1994).',
  missverstaendnisse:['Zuhören heißt nicht zustimmen.','Ein „Ja“ auf eine Zusammenfassung heißt nur „verstanden“, nicht „ich will kaufen“.','Viel Nicken ist kein Zuhören.'],
  ethik:'Was der Kunde im Vertrauen erzählt, darf nicht gegen ihn verwendet werden, etwa um Angst zu verstärken.',
  nichtAbleiten:'Aus der Forschung folgt nicht, dass aktives Zuhören den Abschluss garantiert oder jede Kaufentscheidung verbessert.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Drei-Sätze-Regel',aufgabe:'In deinem nächsten Gespräch meldest du die ersten drei wichtigen Aussagen des Kunden in eigenen Worten zurück, bevor du etwas erklärst.'},{level:'Einsteiger',titel:'Pausen zählen',aufgabe:'Nach jeder offenen Frage innerlich bis vier zählen, bevor du weitersprichst.'},{level:'Fortgeschritten',titel:'Inhalt und Bedeutung trennen',aufgabe:'Notiere nach dem Gespräch zu drei Aussagen: Was hat der Kunde gesagt? Was bedeutet es für ihn? Was habe ich nur vermutet?'},{level:'Fortgeschritten',titel:'Aufzeichnung mit Erlaubnis',aufgabe:'Ein Übungsgespräch mit einer Kollegin aufnehmen und zählen: Wie oft habe ich zurückgemeldet, wie oft Ratschläge gegeben?'}],
  selbsttest:[{f:'Was unterscheidet aktives Zuhören von bloßem Bestätigen („Mhm, verstehe“)?',a:['Es ist freundlicher','Das Gehörte wird in eigenen Worten zurückgemeldet und geprüft','Es dauert länger'],r:1,e:'Das Zurückmelden macht das eigene Verständnis prüfbar.'},{f:'Was zeigte Weger u. a. (2014)?',a:['Aktives Zuhören führt immer zum Abschluss','Menschen fühlten sich durch aktives Zuhören stärker verstanden als durch Ratschläge','Ratschläge sind schädlich'],r:1,e:'Bei Zufriedenheit lagen Ratschläge und Zuhören gleichauf.'},{f:'Ein Kunde bestätigt deine Zusammenfassung mit „Ja, genau“. Was heißt das?',a:['Er will kaufen','Du hast ihn verstanden','Der Einwand ist erledigt'],r:1,e:'Bestätigung des Verstandenen ist keine Kaufentscheidung.'}],
  reflexion:['Wann habe ich zuletzt eine Lösung angeboten, bevor ich das Anliegen ganz verstanden hatte?','Welche Kunden fallen mir schwer zuzuhören, und warum?'],
  kriterien:['Mindestens zwei Zurückmeldungen pro Thema','Jede Deutung mit Prüffrage','Keine Lösung vor der ersten Zusammenfassung','Der Kunde spricht mehr als ich']},
 uebung:[{sit:'Erstgespräch, Kundin kommt wegen ihrer Hausratversicherung.',kunde:'Eigentlich geht es nur um die Hausrat. Aber seit mein Mann gestorben ist, kümmere ich mich um alles allein, und das wächst mir manchmal über den Kopf.',ziel:'Zurückmelden, ohne vom Anliegen abzulenken oder Produkte anzubieten.'},{sit:'Vertragsfälligkeit eines Sparvertrags.',kunde:'Ich will das Geld nicht wieder so lange festlegen. Man weiß ja nie, was kommt.',ziel:'Priorität und Sorge zurückmelden und mit einer offenen Frage prüfen.'}],
 q:['rogersfarson57','rogers57','weger10','weger14','kluger22','kluger24','itz17','ramsey97','itani19','drollinger06','friestad94']});

T({id:'t-spiegeln',titel:'Spiegeltechniken: Überblick und Forschungslage',bereich:'zuhoeren',haupt:true,stufe:'B',kn:['e2','b19'],verkn:['t-paraphrase','t-zusammenfassen','t-emotion','t-nonverbal','t-sprache','t-spiegelgrenzen','t-zuhoeren'],
 schnell:{kern:['„Spiegeln“ meint zwei verschiedene Dinge: verbal zurückmelden, was der Kunde gesagt hat, und nonverbal ähnliches Verhalten zeigen.','Verbales Spiegeln (Paraphrase, Zusammenfassung, Reflexion) ist gut begründet und gehört zum aktiven Zuhören.','Bewusstes Nachahmen der Körpersprache ist schwach und widersprüchlich belegt. Starkes Nachahmen kann Vertrauen senken.','Die Aufmerksamkeit gehört dem Kunden, nicht der eigenen Haltung.'],
  satz:'„Ihnen ist also wichtig, flexibel zu bleiben. Habe ich das richtig verstanden?“',vermeiden:['Körperhaltung kopieren','Jeden Satz wiederholen','Gefühle unterstellen']},
 A:{def:'Spiegeltechniken sind Gesprächsverhalten, bei dem der Zuhörer etwas vom Gesprächspartner aufgreift und zurückgibt. Fachlich sinnvoll ist die Unterscheidung in verbales Spiegeln (Worte, Inhalt, Bedeutung, Gefühl), nonverbale Abstimmung (Haltung, Gestik, Tempo) und sprachliche Anpassung (Wortwahl, Fachsprache, Erklärungstiefe).',
  herkunft:'Das verbale Spiegeln stammt aus der klientenzentrierten Gesprächsführung (Rogers 1957). Die nonverbale Linie stammt aus der Sozialpsychologie der Nachahmung („Chamäleon-Effekt“, Chartrand und Bargh 1999) und der Synchronieforschung. In Verkaufsratgebern werden beide oft vermischt.',
  begriffe:[['Verbales Spiegeln','Inhalt, Bedeutung oder Gefühl in Worten zurückmelden.'],['Mimikry','Unbewusste oder bewusste Nachahmung von Haltung, Gestik, Mimik.'],['Synchronie','Zeitliche Abstimmung von Bewegungen oder Rhythmus zwischen Personen.'],['Sprachstilangleichung','Ähnlicher Gebrauch von Funktionswörtern, Tempo und Ausdrucksweise.']],
  theorie:'Für verbales Spiegeln: Verstehen wird prüfbar und für den Sprecher sichtbar. Für nonverbale Abstimmung: Wahrnehmung und Verhalten sind eng gekoppelt, deshalb passen Menschen sich oft unbewusst an (Chartrand und Bargh 1999). Ob bewusstes Nachahmen dieselbe Wirkung hat, ist eine andere Frage.',
  abgrenzung:'Spiegeln ist kein Sammelbegriff für alle Gesprächstechniken. Fragen, Erklären und Zusammenfassen von Ergebnissen sind eigene Werkzeuge.'},
 B:{text:['Verbales Spiegeln macht sichtbar, dass Information angekommen ist, und lädt zur Korrektur ein.','Natürliche nonverbale Abstimmung ist eher ein Ergebnis guter Beziehung als ihre Ursache. Wer aufmerksam ist, passt sich meist ohnehin an.','Bewusstes Nachahmen lenkt Aufmerksamkeit vom Inhalt auf das eigene Verhalten und kann bemerkt werden. Erkennen Menschen eine Taktik, steigt ihr Misstrauen (Persuasion Knowledge Model).'],
  alternativ:'Positive Laborbefunde zur Nachahmung könnten teils auf Erwartungseffekte und kleine Stichproben zurückgehen. Neuere präregistrierte Studien finden kleinere oder keine Effekte.'},
 C:{aussagen:[
   S('B','Verbales Zurückmelden lässt Gesprächspartner sich stärker verstanden fühlen als Ratschläge oder bloße Bestätigung.',['weger14'],'beleg'),
   S('B','Menschen ahmen Haltung und Gesten anderer häufig unbewusst nach. Empathischere Menschen tun es stärker.',['chartrand99'],'beleg'),
   S('C','Ob Nachahmung Sympathie und Vertrauen erhöht, ist uneinheitlich: Eine präregistrierte Studie fand keine Wirkung auf Rapport und Vertrauen.',['hale16'],'beleg'),
   S('B','Dezente Nachahmung kann Sympathie erhöhen, starke Nachahmung senkte in Experimenten Sympathie und Vertrauen.',['wessler24'],'beleg'),
   S('C','Häufig zitierte Feldstudien zum Spiegeln im Verkauf stammen teils aus Arbeiten, zu denen Verlage Bedenken veröffentlicht oder Rückzüge vorgenommen haben. Sie werden hier nicht als Beleg verwendet.',['retraction'],'beleg')],
  widerspruch:'Ältere Laborstudien berichten deutliche Effekte der Nachahmung auf Sympathie, neuere präregistrierte Arbeiten finden kleinere, keine oder bei starker Nachahmung negative Effekte. Für verbales Spiegeln ist die Lage stabiler.',
  transfer:'Für Beratungsgespräche gibt es kaum direkte Studien zum bewussten Spiegeln. Die Empfehlung lautet daher: verbal spiegeln ja, Körpersprache nicht bewusst kopieren.'},
 D:{wann:'Verbal: bei wichtigen Aussagen, Sorgen, Prioritäten, Einwänden. Nonverbal: gar nicht bewusst, sondern durch Aufmerksamkeit.',ziel:'Verstehen sichern und dem Kunden zeigen, dass er gehört wurde.',
  schritte:['Wichtige Aussage erkennen (Priorität, Sorge, Wunsch).','Passende Form wählen: Schlüsselwort, Paraphrase, Zusammenfassung oder vorsichtige Gefühlsreflexion.','Kurz und in eigenen Worten formulieren.','Mit Prüffrage abschließen.','Antwort des Kunden aufnehmen, nicht sofort weiterargumentieren.'],
  formulierungen:['Schlüsselwort: „Flexibel?“','Paraphrase: „Sie möchten finanziell beweglich bleiben.“','Priorität: „Wichtiger als ein höherer Ertrag ist Ihnen, jederzeit an das Geld zu kommen.“','Gefühl, vorsichtig: „Das klingt, als würde Sie das eher beunruhigen. Liege ich da richtig?“'],
  reaktion:['Bestätigung: vertiefen.','Korrektur: neu fassen, danken.','Irritation („Sag ich doch“): weniger spiegeln, mehr fragen.'],pruefen:'Kunde spricht weiter, präzisiert, korrigiert. Warnzeichen: genervte Kürze, „Genau das habe ich gesagt“.',anpassen:'Spiegeln dosieren: eher bei Wichtigem als bei jeder Aussage.'},
 E:{gut:'Kunde: „Ich möchte nicht noch mehr Geld in Versicherungen stecken. Ich möchte lieber flexibel bleiben.“ Berater: „Ihnen ist also wichtig, finanziell flexibel zu bleiben und sich nicht durch zusätzliche laufende Beiträge einzuschränken.“ Danach: „Was müsste eine Lösung mitbringen, damit sie zu dieser Flexibilität passt, oder ist das Thema für Sie gerade ganz erledigt?“',
  schlecht:'Berater lehnt sich wie der Kunde zurück, verschränkt wie er die Arme und sagt: „Flexibilität ist wichtig, darum ist unser Tarif genau richtig.“ (kopiert Körpersprache und vereinnahmt die Aussage)',
  dialog:[['K','Ich möchte nicht noch mehr Geld in Versicherungen stecken. Ich möchte lieber flexibel bleiben.'],['B','Ihnen ist also wichtig, finanziell flexibel zu bleiben und sich nicht durch zusätzliche laufende Beiträge einzuschränken.'],['K','Genau. Ich zahle schon genug.'],['B','Was heißt für Sie „genug“: geht es um den Betrag oder eher darum, nicht noch einen festen Vertrag zu haben?'],['K','Eher um die Bindung. Den Betrag könnte ich schon stemmen.']],
  analyse:'Die Zusammenfassung macht die Priorität (Flexibilität, keine neue Bindung) sichtbar und gibt dem Kunden die Kontrolle. Die offene Rückfrage prüft, ob „genug“ den Betrag oder die Bindung meint. So wird ein scheinbarer Preiseinwand als Wunsch nach Flexibilität erkennbar, ohne dass er unterstellt wurde.',
  alternative:'Ebenso respektvoll wäre: „Dann lassen wir das Thema heute weg. Ist das für Sie in Ordnung?“ Ein Nein bleibt ein gutes Ergebnis.',
  finanz:'Bei einer Wiederanlage: „Sie möchten Ertrag, aber nicht um den Preis, dass das Geld lange festliegt. Habe ich die Reihenfolge richtig?“',
  allgemein:'Beim Küchenkauf: „Ihnen ist die Arbeitsfläche wichtiger als das Design der Fronten. Stimmt das?“'},
 F:{nicht:['Wenn Spiegeln mechanisch wird und der Kunde es bemerkt.','Bei falschen Gefühlsdeutungen.','Wenn der Kunde Fakten will, keine Reflexion.'],manipulativ:'Wenn Körpersprache gezielt kopiert wird, um Sympathie zu erzeugen, oder wenn Spiegeln dazu dient, Zustimmung zu erzwingen („Sie wollen also auch Sicherheit für Ihre Familie, richtig?“).',
  missverstaendnisse:['Spiegeln erzeugt nicht automatisch Vertrauen.','Ähnliche Körperhaltung zeigt keine Kaufbereitschaft an.','Ein „Ja“ auf die Spiegelung ist keine Zustimmung zum Angebot.'],ethik:'Spiegeln ist eine Hilfe zum Verstehen, kein Hebel zur Beeinflussung.',nichtAbleiten:'Aus der Mimikry-Forschung folgt nicht, dass bewusstes Nachahmen im Kundengespräch Vertrauen schafft.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Vier Formen erkennen',aufgabe:'Nimm eine Kundenaussage und schreibe vier Antworten: Schlüsselwort, Paraphrase, Priorität, vorsichtige Gefühlsreflexion.'},{level:'Fortgeschritten',titel:'Spiegeln dosieren',aufgabe:'In einem Übungsgespräch nur bei den drei wichtigsten Aussagen spiegeln. Danach: Welche waren es und warum?'}],
  selbsttest:[{f:'Welche Form des Spiegelns ist am besten belegt?',a:['Körperhaltung kopieren','Verbales Zurückmelden des Inhalts','Sprechtempo exakt angleichen'],r:1,e:'Verbales Spiegeln gehört zum gut untersuchten aktiven Zuhören.'},{f:'Was fanden Wessler u. a. (2024) zu starker Nachahmung?',a:['Mehr Vertrauen','Kein Effekt','Weniger Sympathie und Vertrauen'],r:2,e:'Starke Nachahmung schadete, dezente half leicht.'}],
  reflexion:['Wo habe ich schon einmal „gespiegelt“, um zu überzeugen statt zu verstehen?'],kriterien:['Spiegelung in eigenen Worten','Prüffrage am Ende','Keine Unterstellung','Kein Körperkopieren']},
 uebung:[{sit:'Bestandskunde, Gespräch über eine Krankenzusatzversicherung.',kunde:'Ich möchte nicht noch mehr Geld in Versicherungen stecken. Ich möchte lieber flexibel bleiben.',ziel:'Priorität spiegeln und mit einer offenen Frage prüfen, ohne zu überreden.'}],
 q:['rogers57','chartrand99','weger14','hale16','wessler24','mogan17','friestad94','retraction']});

T({id:'t-paraphrase',titel:'Verbales Spiegeln: Schlüsselwort, Paraphrase, Priorität',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'B',kn:['e2','c9'],verkn:['t-zusammenfassen','t-emotion'],
 schnell:{kern:['Schlüsselwort: ein wichtiges Wort fragend wiederholen, lädt zum Weitererzählen ein.','Paraphrase: Inhalt in eigenen Worten, nicht wortgleich.','Priorität spiegeln: herausarbeiten, was dem Kunden wichtiger ist als anderes.','Immer mit Prüffrage enden.'],satz:'„Sicherheit ist Ihnen also wichtiger als die Rendite, sehe ich das richtig?“',vermeiden:['Papageien-Wiederholung','Eigene Deutung als Kundenwort ausgeben']},
 A:{def:'Verbales Spiegeln umfasst Techniken, mit denen der Zuhörer Gesagtes in Worten zurückgibt. Unterschieden werden das Aufgreifen eines Schlüsselworts, das Aufgreifen einer Formulierung, die Paraphrase (Inhalt in eigenen Worten), das Spiegeln von Zielen und Prioritäten und die verbale Bestätigung des Verstandenen.',herkunft:'Klientenzentrierte Gesprächsführung (Rogers 1957), später Motivational Interviewing (Miller und Rollnick 2013).',
  begriffe:[['Schlüsselwort','„Flexibel?“ Ein Wort, fragend betont.'],['Einfache Reflexion','Nahe am Gesagten.'],['Komplexe Reflexion','Fügt Bedeutung hinzu, etwa eine Priorität. Muss geprüft werden.'],['Bestätigung des Verstandenen','„Ich habe verstanden, dass …“']],
  theorie:'Je weiter eine Reflexion vom Wortlaut weggeht, desto mehr Deutung enthält sie. Mehr Deutung kann tieferes Verständnis zeigen, ist aber riskanter.',abgrenzung:'Die Paraphrase gibt den Inhalt wieder. Die Gefühlsreflexion gibt das Gefühl wieder. Die Zusammenfassung bündelt mehrere Aussagen.'},
 B:{text:['Das Schlüsselwort richtet die Aufmerksamkeit des Sprechers auf einen Punkt und lädt ein, ihn auszuführen.','Die Paraphrase zeigt Verarbeitung. Wortgleiches Wiederholen zeigt nur Gedächtnis.','Das Spiegeln einer Priorität macht eine Rangfolge sichtbar, die der Kunde vielleicht selbst noch nicht ausgesprochen hat. Das hilft bei Entscheidungen, setzt aber eine Prüfung voraus.'],alternativ:'Manche Gesprächspartner empfinden häufige Paraphrasen als Gesprächstechnik. Dann wirkt eine schlichte Folgefrage natürlicher.'},
 C:{aussagen:[S('B','Zurückmelden lässt Gesprächspartner sich stärker verstanden fühlen als Ratschläge.',['weger14'],'beleg'),S('C','Die Paraphrase allein beeinflusst vor allem die Einschätzung der Zuhörkompetenz.',['weger10'],'beleg'),S('B','Folgefragen, die an das Gesagte anknüpfen, erhöhen Sympathie über wahrgenommene Responsivität.',['huang17'],'beleg'),S('D','Prioritäten zu spiegeln hilft Kunden bei der Entscheidung. Das ist eine Praxisregel, keine direkt geprüfte Aussage.',[],'heuristik')],
  widerspruch:'Für die einzelnen Formen (Schlüsselwort, Prioritätsspiegelung) gibt es kaum getrennte Studien. Die Belege betreffen Zurückmelden insgesamt.',transfer:'Studien aus Kennenlern- und Laborgesprächen. Übertragung auf Beratung plausibel, nicht direkt geprüft.'},
 D:{wann:'Bei Aussagen mit Gewicht: Wünsche, Ziele, Sorgen, Abwägungen.',ziel:'Verstehen und Rangfolge klären.',schritte:['Schlüsselwort hören (etwa „flexibel“, „sicher“, „Familie“).','Wählen: Schlüsselwort fragend aufgreifen oder paraphrasieren.','Bei mehreren Wünschen: Rangfolge vorsichtig spiegeln.','Prüffrage stellen.'],
  formulierungen:['„Flexibel?“','„Sie meinen, Sie wollen jederzeit an das Geld kommen.“','„Wenn ich das richtig höre, ist Ihnen Sicherheit wichtiger als Ertrag.“','„Ich habe verstanden: erst die Renovierung, dann die Vorsorge. Stimmt die Reihenfolge?“'],reaktion:['Bei „Nein, eher …“: Rangfolge neu fassen.'],pruefen:'Der Kunde ordnet von sich aus weiter.',anpassen:'Bei knappen Kunden eher Schlüsselwort als lange Paraphrase.'},
 E:{gut:'Kunde: „Für mich zählt, dass meine Frau versorgt ist.“ Berater: „Versorgt, das heißt für Sie …?“',schlecht:'Berater: „Sie wollen also eine Risikolebensversicherung über 300.000 €.“ (fügt Produkt und Zahl hinzu, die der Kunde nicht genannt hat)',
  dialog:[['K','Ich will mich nicht wieder zehn Jahre binden.'],['B','Zehn Jahre sind Ihnen zu lang.'],['K','Ja, wir wissen noch nicht, ob wir umziehen.'],['B','Ein möglicher Umzug macht Ihnen eine lange Bindung schwer. Was wäre ein Zeitraum, mit dem Sie gut leben könnten?']],
  analyse:'Erst einfache Reflexion, dann Bedeutung (Umzug), dann offene Frage zur Lösung.',alternative:'„Wie sicher ist der Umzug?“ wäre ebenfalls passend, aber stärker auf Fakten gerichtet.',finanz:'Fondsparplan: „Schwankungen stören Sie nicht, solange Sie in fünf Jahren an das Geld kommen. Richtig?“',allgemein:'Hotelbuchung: „Ruhe ist wichtiger als Meerblick?“'},
 F:{nicht:['Wenn jede Aussage gespiegelt wird.'],manipulativ:'Wenn die Paraphrase eine Zustimmung einbaut, die nicht gesagt wurde.',missverstaendnisse:['Paraphrase heißt nicht, die Worte des Kunden zu ersetzen, um ihn umzudeuten.'],ethik:'Keine Umdeutung zum eigenen Vorteil.',nichtAbleiten:'Dass gespiegelte Prioritäten automatisch zu einem Abschluss führen.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Vom Wort zur Paraphrase',aufgabe:'Fünf Kundensätze: je einmal Schlüsselwort, einmal Paraphrase schreiben.'},{level:'Fortgeschritten',titel:'Rangfolge spiegeln',aufgabe:'Kunde nennt drei Wünsche. Formuliere eine Prioritätsspiegelung mit Prüffrage, ohne eine Reihenfolge zu erfinden.'}],
  selbsttest:[{f:'Kunde: „Ich hätte gern Sicherheit, aber auch etwas Ertrag.“ Welche Antwort spiegelt, ohne zu unterstellen?',a:['„Sicherheit ist Ihnen also wichtiger.“','„Sie möchten beides. Wenn Sie sich entscheiden müssten, was hätte Vorrang?“','„Dann nehmen wir den Garantietarif.“'],r:1,e:'Die Rangfolge wurde nicht genannt und muss erfragt werden.'}],reflexion:['Welche Wörter meiner Kunden höre ich oft und greife sie nicht auf?'],kriterien:['Eigene Worte','Keine hinzugefügten Fakten','Prüffrage']},
 uebung:[{sit:'Wiederanlage nach Fälligkeit.',kunde:'Ich will natürlich, dass das Geld was bringt. Aber ich hab auch keine Lust, nachts wach zu liegen, wenn die Börse fällt.',ziel:'Beide Wünsche spiegeln und die Rangfolge erfragen.'}],q:['rogers57','miller13','weger10','weger14','huang17']});

T({id:'t-zusammenfassen',titel:'Zusammenfassen und Hypothesen prüfen',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'B',kn:['c16','e3'],verkn:['t-paraphrase','t-emotion','t-erklaeren'],
 schnell:{kern:['Unterscheide: wiederholen, paraphrasieren, zusammenfassen, Priorität herausarbeiten, Gefühl vorsichtig spiegeln, Hypothese prüfen.','Eine Zusammenfassung bündelt mehrere Aussagen und schafft Orientierung.','Was der Kunde nicht gesagt hat, ist eine Hypothese und wird als Frage formuliert.','Teach-back: Der Kunde fasst selbst zusammen.'],satz:'„Ich fasse kurz zusammen, was ich verstanden habe, und Sie korrigieren mich bitte.“',vermeiden:['Motive unterstellen','Zusammenfassung als Abschlussfalle']},
 A:{def:'Zusammenfassen heißt, mehrere Aussagen des Kunden geordnet in eigenen Worten wiederzugeben. Eine Hypothese ist eine Vermutung über Bedeutung oder Motiv, die der Kunde nicht ausgesprochen hat.',herkunft:'Zusammenfassen ist ein Kernelement im Motivational Interviewing und in der Gesprächsführung allgemein. Die Rückerklär-Methode (Teach-back) stammt aus der Gesundheitskommunikation.',
  begriffe:[['Bloßes Wiederholen','Wortgleich. Zeigt Gedächtnis, nicht Verständnis.'],['Paraphrase','Ein Inhalt in eigenen Worten.'],['Sammelnde Zusammenfassung','Mehrere Aussagen gebündelt.'],['Priorität herausarbeiten','Rangfolge benennen, nur wenn erkennbar, sonst erfragen.'],['Vorsichtige Gefühlsspiegelung','Gefühl als Möglichkeit benennen.'],['Hypothese','Vermutung, die erst bestätigt werden muss.'],['Teach-back','Der Gesprächspartner erklärt selbst in eigenen Worten.']],
  theorie:'Zusammenfassungen entlasten das Arbeitsgedächtnis beider Seiten und strukturieren das Gespräch (Sweller 1988 zur kognitiven Belastung, übertragen). Der Bestätigungsfehler (Nickerson 1998) erklärt, warum eigene Vermutungen gern als Tatsachen behandelt werden.',abgrenzung:'Die Zusammenfassung des Kunden ist etwas anderes als die Zusammenfassung des Angebots oder des Ergebnisses.'},
 B:{text:['Zusammenfassungen zeigen, dass der Zuhörer den Überblick hat, und geben dem Kunden einen Moment, die eigene Lage von außen zu sehen.','Menschen neigen dazu, Informationen passend zu ihrer ersten Annahme zu deuten (Bestätigungsfehler). Die ausdrückliche Prüffrage ist ein Gegenmittel.','Wenn der Kunde selbst zusammenfasst (Teach-back), wird sichtbar, was wirklich verstanden wurde.'],alternativ:'Zusammenfassungen können auch als Steuerungsinstrument wirken, wenn nur ausgewählte Punkte wiedergegeben werden.'},
 C:{aussagen:[S('B','Die Rückerklär-Methode war in 19 von 20 Studien wirksam, etwa für Wissen und Verständnis.',['talevski20'],'transfer'),S('B','Der Bestätigungsfehler ist ein gut dokumentiertes, verbreitetes Phänomen.',['nickerson98'],'beleg'),S('C','Reflektierende Techniken verstärken die Äußerung beider Seiten einer Abwägung (Veränderungs- und Beibehaltungssprache).',['magill18','baldwin17'],'transfer'),S('D','Eine Zusammenfassung pro Themenblock ist eine bewährte Praxisregel.',[],'heuristik')],
  widerspruch:'Für Zusammenfassungen im Vertrieb gibt es keine direkten Experimente.',transfer:'Teach-back stammt aus dem Gesundheitswesen, die Übertragung auf Finanzthemen ist plausibel, weil beide komplex sind.'},
 D:{wann:'Nach jedem Themenblock, vor einem Themenwechsel, vor einer Empfehlung, am Ende.',ziel:'Gemeinsames Verständnis sichern.',schritte:['Ankündigen: „Ich fasse kurz zusammen.“','Zwei bis vier Punkte in Kundenworten.','Gesagtes und Vermutetes trennen: „Gesagt haben Sie … Ich frage mich, ob …“','Prüffrage stellen.','Bei komplexen Inhalten Teach-back anbieten.'],
  formulierungen:['„Bisher habe ich verstanden: erstens …, zweitens …, und offen ist noch … Passt das?“','„Gesagt haben Sie, dass … Ich frage mich, ob auch … eine Rolle spielt. Ist das so, oder liege ich daneben?“','„Damit ich sehe, ob ich es verständlich erklärt habe: Wie würden Sie es Ihrem Partner erklären?“'],reaktion:['Kunde ergänzt: in die Zusammenfassung aufnehmen.','Kunde verneint die Hypothese: verwerfen, nicht wiederholen.'],pruefen:'Kunde bestätigt oder korrigiert konkret.',anpassen:'Kurz halten, wenn der Kunde ungeduldig ist.'},
 E:{gut:'„Ich habe drei Dinge verstanden: Das Haus ist abbezahlt, die Kinder sind aus dem Haus, und Sie möchten, dass Ihre Frau im Pflegefall nicht alles allein stemmen muss. Habe ich etwas vergessen?“',schlecht:'„Sie haben also Angst, dass Ihre Kinder das Erbe für Ihre Pflege ausgeben müssen.“ (unterstellt eine Angst, die nicht genannt wurde)',
  dialog:[['B','Ich fasse kurz zusammen: Die Rente wird knapp, Sie möchten aber nicht noch einen Vertrag. Und Sie überlegen, ob die Wohnung verkauft wird. Stimmt das so?'],['K','Fast. Verkauf ist eigentlich vom Tisch.'],['B','Danke, dann streiche ich den Verkauf. Bleibt: Rente knapp, kein neuer Vertrag. Was wäre für Sie denn eine gute Lösung, wenn nicht ein neuer Vertrag?']],
  analyse:'Die Korrektur wird dankend aufgenommen. Die Zusammenfassung wird angepasst, nicht verteidigt.',alternative:'Zuerst den Kunden selbst zusammenfassen lassen: „Was war für Sie heute das Wichtigste?“',finanz:'Nach Erklärung des Eigenanteils im Pflegeheim: „Wie würden Sie Ihrer Tochter erklären, was die Pflegekasse zahlt und was bei Ihnen bleibt?“',allgemein:'Nach einer Handwerkerberatung: „Fassen wir zusammen: Erst das Dach, die Fenster nächstes Jahr. Richtig?“'},
 F:{nicht:['Wenn die Zusammenfassung länger ist als das Gesagte.'],manipulativ:'Wenn Zusammenfassungen gezielt Punkte weglassen, die gegen ein Produkt sprechen, oder als „Ja-Kette“ zum Abschluss eingesetzt werden.',missverstaendnisse:['Ein „Ja“ zur Zusammenfassung ist keine Kaufzusage.'],ethik:'Auch Einwände und Gegenargumente in die Zusammenfassung aufnehmen.',nichtAbleiten:'Dass Teach-back im Finanzbereich nachweislich bessere Entscheidungen bewirkt.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Gesagt oder vermutet?',aufgabe:'Nach einem Gespräch zehn Notizen markieren: G für gesagt, V für vermutet.'},{level:'Fortgeschritten',titel:'Teach-back üben',aufgabe:'Erkläre einer Kollegin den Pflege-Eigenanteil und bitte sie, es in eigenen Worten wiederzugeben. Wo hakt es?'}],
  selbsttest:[{f:'Welche Formulierung ist eine Hypothese, korrekt als Frage?',a:['„Sie haben Angst vor Altersarmut.“','„Ich frage mich, ob auch die Sorge um die Rente eine Rolle spielt. Ist das so?“','„Sie wollen also mehr vorsorgen.“'],r:1,e:'Vermutungen werden als prüfbare Frage formuliert.'}],reflexion:['Welche Vermutung über einen Kunden habe ich zuletzt nie überprüft?'],kriterien:['Gesagtes und Vermutetes getrennt','Einwände enthalten','Prüffrage']},
 uebung:[{sit:'Ende eines Gesprächs über Altersvorsorge, keine Entscheidung.',kunde:'Ich muss das alles erst mal sacken lassen. Es war viel heute.',ziel:'Fair zusammenfassen, auch die Bedenken, und einen nächsten Schritt anbieten ohne Druck.'}],q:['talevski20','nickerson98','magill18','baldwin17','sweller88','miller13']});

T({id:'t-emotion',titel:'Emotionale Reflexion und Bedeutungsreflexion',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'C',kn:['e5','j8'],verkn:['t-zusammenfassen','t-mi','t-rapport'],
 schnell:{kern:['Gefühle nur vorsichtig und als Möglichkeit benennen.','Bedeutungsreflexion: Was heißt das für den Kunden?','Falsch gedeutete Gefühle schaden mehr als gar keine Deutung.','Wie Empathie ankommt, zählt mehr als treffsicheres Gedankenlesen.'],satz:'„Das klingt, als hätte Sie das ziemlich belastet. Ist das so?“',vermeiden:['„Sie haben Angst …“','Gefühle bewerten','Emotion für Verkaufsargumente nutzen']},
 A:{def:'Emotionale Reflexion benennt ein Gefühl, das hinter einer Aussage hörbar ist. Bedeutungsreflexion benennt, was eine Situation für den Kunden bedeutet, etwa Werte, Ziele oder Folgen.',herkunft:'Klientenzentrierte Psychotherapie (Rogers 1957). Empathie ist dort eine zentrale Beziehungsbedingung.',
  begriffe:[['Gefühlsreflexion','„Das klingt enttäuschend.“'],['Bedeutungsreflexion','„Es geht Ihnen also weniger ums Geld als darum, niemandem zur Last zu fallen.“'],['Empathie-Genauigkeit','Wie treffsicher ein Gefühl erkannt wird.'],['Wahrgenommene Empathie','Wie sehr sich das Gegenüber verstanden fühlt.']],theorie:'Wer sich emotional verstanden fühlt, erlebt weniger Bedrohung und kann eher offen nachdenken (vgl. Itzchakov u. a. 2017).',abgrenzung:'Reflexion ist kein Trost und keine Bewertung. Sie ist auch keine Diagnose.'},
 B:{text:['Gefühle beeinflussen, welche Informationen jemand aufnehmen kann. Ein benanntes Gefühl verliert oft an Druck.','Eine falsche Deutung signalisiert, dass man nicht zugehört hat, und kann Vertrauen beschädigen.','Bedeutungsreflexion verbindet Fakten mit Werten. Das ist für Vorsorgeentscheidungen zentral.'],alternativ:'Manche Menschen möchten über Gefühle im geschäftlichen Rahmen nicht sprechen. Dann wirkt Gefühlsreflexion übergriffig.'},
 C:{aussagen:[S('B','In der Psychotherapie ist Empathie ein mittelstarker Prädiktor des Ergebnisses. Die Wahrnehmung durch Klienten sagte mehr voraus als die Treffsicherheit.',['elliott18'],'transfer'),S('C','Hochwertiges Zuhören senkte in Experimenten soziale Ängstlichkeit und abwehrende Verarbeitung.',['itz17'],'transfer'),S('D','Vorsichtige Formulierungen („Das klingt, als …“) verringern das Risiko falscher Deutung. Praxisregel ohne direkte Studie.',[],'heuristik')],widerspruch:'Für Gefühlsreflexion im Verkauf gibt es keine direkten Studien. Psychotherapeutische Befunde sind nicht ohne Weiteres übertragbar.',transfer:'Übertragung mit Vorsicht. Beratung ist keine Therapie, und Kunden haben ein anderes Anliegen.'},
 D:{wann:'Wenn ein Gefühl deutlich hörbar ist (Ärger, Sorge, Trauer, Erleichterung) oder der Kunde von bedeutsamen Ereignissen erzählt.',ziel:'Anerkennen, dass das Thema den Kunden bewegt, und Raum geben.',schritte:['Gefühl hören, nicht erraten.','Als Möglichkeit benennen.','Pause lassen.','Bedeutung erfragen oder vorsichtig benennen.','Zum Anliegen zurück, wenn der Kunde bereit ist.'],
  formulierungen:['„Das klingt, als hätte Sie das geärgert.“','„Ich höre heraus, dass Ihnen das nicht egal ist.“','„Es geht Ihnen offenbar weniger um den Betrag als darum, unabhängig zu bleiben. Liege ich da richtig?“'],reaktion:['Kunde verneint: „Danke, dann habe ich das falsch verstanden.“','Kunde wird emotional: Zeit lassen, nicht sofort weiter.'],pruefen:'Kunde spricht offener weiter.',anpassen:'Bei sachlichen Kunden auf Bedeutung statt Gefühl zielen.'},
 E:{gut:'Kunde: „Die letzte Beitragserhöhung kam ohne jede Erklärung.“ Berater: „Das hat Sie geärgert, verständlicherweise. Wollen wir uns zuerst anschauen, woher die Erhöhung kommt?“',schlecht:'„Sie sind ja richtig wütend!“ (übertreibt und bewertet)',dialog:[['K','Ich will einfach nicht, dass meine Kinder mal für mich zahlen müssen.'],['B','Ihre Unabhängigkeit gegenüber den Kindern ist Ihnen wichtig.'],['K','Ja, meine Eltern waren so, das war nicht schön.'],['B','Das haben Sie selbst erlebt. Was hätte es damals leichter gemacht?']],
  analyse:'Bedeutungsreflexion statt Gefühlsunterstellung. Die Folgefrage lässt den Kunden selbst die Lösungsrichtung finden.',alternative:'Keine Reflexion, sondern Schweigen und Nicken ist ebenfalls angemessen.',finanz:'Nach Erbfall: „Das ist sicher keine leichte Zeit. Wir müssen heute nichts entscheiden.“',allgemein:'Reklamation: „Das war ärgerlich für Sie. Was wäre jetzt eine faire Lösung?“'},
 F:{nicht:['Bei Kunden, die Distanz wollen.','Wenn das Gefühl nur vermutet ist.'],manipulativ:'Emotionen benennen, um sie zu verstärken („Stellen Sie sich vor, Ihre Familie steht ohne Geld da …“).',missverstaendnisse:['Empathie heißt nicht, Gefühle zu teilen oder zu übernehmen.'],ethik:'Belastete Situationen (Tod, Krankheit) sind kein Verkaufsanlass. Entscheidungen dürfen vertagt werden.',nichtAbleiten:'Dass Empathie im Verkauf die gleichen Effekte hat wie in der Therapie.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Gefühlswörter sammeln',aufgabe:'Liste zehn Gefühlswörter jenseits von „gut“ und „schlecht“, die in Beratungen vorkommen.'},{level:'Fortgeschritten',titel:'Bedeutung statt Gefühl',aufgabe:'Formuliere zu drei Aussagen eine Bedeutungsreflexion ohne Gefühlswort.'}],selbsttest:[{f:'Was sagte in der Meta-Analyse von Elliott u. a. das Ergebnis besser voraus?',a:['Empathie-Genauigkeit','Wie Empathie beim Gegenüber ankommt','Dauer des Gesprächs'],r:1,e:'Wahrgenommene Empathie zählte mehr.'}],reflexion:['Wann habe ich ein Gefühl unterstellt, das nicht da war?'],kriterien:['Möglichkeitsform','Keine Bewertung','Pause danach']},
 uebung:[{sit:'Witwer, Gespräch über die Hausratversicherung.',kunde:'Das hat immer meine Frau gemacht. Ich hab ehrlich gesagt keine Ahnung, was wir da haben.',ziel:'Anerkennen, ohne zu dramatisieren, und Unterstützung beim Sortieren anbieten.'}],q:['rogers57','elliott18','itz17']});

T({id:'t-nonverbal',titel:'Nonverbale Synchronie und Mimikry',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'C',kn:['b5','j3','j4'],verkn:['t-spiegelgrenzen','t-rapport','t-eindruck'],
 schnell:{kern:['Menschen passen sich oft unbewusst an: Haltung, Tempo, Rhythmus.','Natürliche Abstimmung entsteht aus Aufmerksamkeit. Bewusstes Kopieren ist etwas anderes.','Die Forschung zur Wirkung bewussten Nachahmens ist widersprüchlich, starke Nachahmung kann schaden.','Körpersprache erlaubt keine sicheren Schlüsse auf Sympathie oder Kaufbereitschaft.'],satz:'Statt Haltung zu kopieren: zugewandt sitzen, Tempo nicht überfahren, Pausen lassen.',vermeiden:['Gesten kopieren','„Spiegeln, um zu führen“','Körpersprache deuten wie ein Lügendetektor']},
 A:{def:'Nonverbale Synchronie bezeichnet die zeitliche Abstimmung von Bewegungen, Rhythmus und Ausdruck zwischen Personen. Mimikry bezeichnet die Nachahmung von Haltung, Gestik oder Mimik. Beides kann unbewusst geschehen oder bewusst herbeigeführt werden.',herkunft:'Sozialpsychologie der Nachahmung (Chartrand und Bargh 1999), Rapportforschung (Tickle-Degnen und Rosenthal 1990), Synchronieforschung (Mogan u. a. 2017).',
  begriffe:[['Interpersonale Synchronie','Gleichzeitige oder rhythmisch abgestimmte Bewegung.'],['Mimikry','Nachahmen konkreter Verhaltensweisen.'],['Mimische Abstimmung','Angleichung von Gesichtsausdrücken.'],['Prosodie','Sprechtempo, Pausen, Stimmführung.']],theorie:'Die enge Kopplung von Wahrnehmung und Handlung führt zu unbewusster Nachahmung. Koordination gilt als ein Bestandteil von Rapport, der vor allem in länger bestehenden Beziehungen wichtig wird (Tickle-Degnen und Rosenthal 1990).',abgrenzung:'Natürliche Abstimmung im Gespräch ist etwas anderes als die Verkaufsempfehlung, die Körperhaltung des Kunden bewusst nachzumachen.'},
 B:{text:['Wer aufmerksam ist, passt Tempo und Lautstärke meist von selbst an.','Bewusstes Kopieren bindet Aufmerksamkeit, die beim Kunden fehlt.','Wird Nachahmung bemerkt, wird sie als Taktik gedeutet und kann Misstrauen auslösen.'],alternativ:'Positive Befunde könnten darauf beruhen, dass Nachahmung ein Zeichen bereits bestehender Sympathie ist und nicht deren Ursache.'},
 C:{aussagen:[S('B','Unbewusste Nachahmung im Gespräch ist gut dokumentiert.',['chartrand99'],'beleg'),S('C','Synchronie zeigt in einer Meta-Analyse schwache bis mittlere Wirkungen auf prosoziales Verhalten. Spätere Arbeiten sehen Verzerrung durch Erwartungseffekte.',['mogan17'],'beleg'),S('C','Eine präregistrierte Studie fand keine Wirkung von Nachahmung auf Rapport oder Vertrauen.',['hale16'],'beleg'),S('B','Dezente Nachahmung erhöhte Sympathie, starke senkte Sympathie und Vertrauen.',['wessler24'],'beleg'),S('B','Der Satz „7 % Worte, 38 % Stimme, 55 % Körpersprache“ beruht auf Experimenten zu widersprüchlichen Gefühlsbotschaften und gilt nicht für Gespräche allgemein.',['mehrabian67'],'beleg')],
  widerspruch:'Die Befundlage zur bewussten Nachahmung ist gemischt. Verkaufsfeldstudien mit großen Effekten sind teils wegen Zweifeln an der Datenqualität nicht verwendbar.',transfer:'Keine verlässlichen Studien zu bewusstem Spiegeln in Versicherungsgesprächen.'},
 D:{wann:'Nicht als Technik. Stattdessen Grundregeln guter Zuwendung.',ziel:'Eine ruhige, zugewandte Gesprächsatmosphäre.',schritte:['Zugewandt sitzen, Blickkontakt halten, ohne zu starren.','Sprechtempo nicht schneller als der Kunde.','Pausen zulassen.','Auf Inhalt achten, nicht auf die eigene Haltung.'],formulierungen:['(Nonverbal) Notizen ankündigen: „Ich schreibe kurz mit, damit nichts verloren geht.“'],reaktion:['Kunde lehnt sich zurück, verschränkt Arme: nicht deuten, sondern fragen, ob etwas unklar ist.'],pruefen:'Atmosphäre ruhig, Kunde spricht frei.',anpassen:'Bei schnellen Kunden etwas zügiger, aber klar bleiben.'},
 E:{gut:'Berater merkt, dass er schneller spricht als die Kundin, und verlangsamt bewusst sein eigenes Tempo, ohne ihren Tonfall nachzumachen.',schlecht:'Berater lehnt sich zurück, sobald der Kunde es tut, und verschränkt ebenfalls die Arme.',dialog:[['K','(lehnt sich zurück, verschränkt die Arme) Hm.'],['B','Ich habe gerade viel auf einmal erklärt. Ist etwas dabei, das nicht passt oder unklar ist?'],['K','Ehrlich gesagt verstehe ich den Unterschied zwischen den Tarifen nicht.']],analyse:'Statt Körpersprache zu deuten oder zu kopieren, fragt der Berater nach. Verschränkte Arme können vieles bedeuten, auch Kälte im Raum.',alternative:'Kurz innehalten und zusammenfassen.',finanz:'Bei Video-Beratung: Kamera auf Augenhöhe, Pausen aushalten, nicht ins Bild hineinreden.',allgemein:'Am Verkaufstresen: dem Kunden zugewandt, nicht nebenbei tippen.'},
 F:{nicht:['Bewusstes Nachahmen fällt auf, besonders bei aufmerksamen Kunden.','Kulturelle Unterschiede bei Blickkontakt und Nähe.'],manipulativ:'Nachahmung als „Rapport-Technik“, um Widerstand zu senken.',missverstaendnisse:['Ähnliche Haltung bedeutet keine Kaufbereitschaft.','Verschränkte Arme bedeuten nicht automatisch Ablehnung.'],ethik:'Keine verdeckten Beeinflussungstechniken.',nichtAbleiten:'Dass Kopieren der Körperhaltung Vertrauen erzeugt.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Eigenes Tempo beobachten',aufgabe:'In einem Gespräch auf das eigene Sprechtempo achten und nach jeder Erklärung eine Pause lassen.'},{level:'Fortgeschritten',titel:'Deuten durch Fragen ersetzen',aufgabe:'Bei jedem Körpersignal, das du deuten möchtest, stattdessen eine offene Frage stellen.'}],selbsttest:[{f:'Was ist die belegte Kernaussage zur Mimikry?',a:['Kopieren schafft Vertrauen','Menschen ahmen oft unbewusst nach, bewusstes Kopieren wirkt unsicher und bei starker Ausprägung negativ','Körpersprache macht 55 % aus'],r:1,e:'So fasst die aktuelle Befundlage es zusammen.'}],reflexion:['Welche Körpersignale deute ich vorschnell?'],kriterien:['Aufmerksamkeit beim Kunden','Keine Deutung ohne Nachfrage']},
 uebung:[{sit:'Kunde wird still und schaut auf die Uhr.',kunde:'(schaut auf die Uhr) Ja, ja.',ziel:'Nicht deuten, sondern freundlich klären, ob Zeit oder Inhalt das Problem ist.'}],q:['chartrand99','tickle90','mogan17','hale16','wessler24','mehrabian67','retraction']});

T({id:'t-sprache',titel:'Sprachliche Anpassung: Wortwahl, Fachsprache, Erklärungstiefe',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'C',kn:['f6','b19','j1'],verkn:['t-erklaeren','t-nonverbal'],
 schnell:{kern:['Anpassen heißt: Wortwahl, Tempo und Erklärungstiefe auf den Kunden einstellen, nicht seine Ausdrucksweise imitieren.','Fachbegriffe des Kunden aufgreifen, eigene erklären.','Informationsdichte senken: wenige Punkte, klare Reihenfolge.','Verständnis prüfen statt voraussetzen.'],satz:'„Darf ich kurz erklären, was mit Eigenanteil gemeint ist?“',vermeiden:['Dialekt oder Jugendsprache nachmachen','Fachchinesisch als Kompetenzbeweis']},
 A:{def:'Sprachliche Anpassung bezeichnet, wie ein Sprecher Wortwahl, Abstraktionsniveau, Tempo und Informationsdichte an den Gesprächspartner anpasst. In der Kommunikationswissenschaft wird das als Kommunikationsakkommodation beschrieben, in der Sprachpsychologie als Sprachstilangleichung (Language Style Matching).',herkunft:'Kommunikationsakkommodationstheorie (Giles und Kollegen), Sprachstilforschung (Ireland u. a. 2011).',begriffe:[['Konvergenz','Annäherung des Sprachstils.'],['Divergenz','Bewusste Abgrenzung.'],['Funktionswörter','Pronomen, Artikel, Präpositionen. Ihr ähnlicher Gebrauch wird in der Forschung gemessen.'],['Informationsdichte','Menge neuer Information pro Satz.']],theorie:'Sprachstilangleichung entsteht vor allem unbewusst aus geteilter Aufmerksamkeit. Gezielte Anpassung an das Verständnisniveau ist dagegen eine Frage der Verständlichkeit (Sweller 1988, kognitive Belastung).',abgrenzung:'Angleichen an das Verständnis ist sinnvoll. Nachahmen des Sprechstils ist etwas anderes und kann herablassend wirken.'},
 B:{text:['Fremdwörter erhöhen die kognitive Belastung und senken das Verständnis.','Wer die Begriffe des Kunden übernimmt, zeigt Zuhören und vermeidet Übersetzungsfehler.','Eine zu einfache Sprache gegenüber Fachleuten kann als Geringschätzung empfunden werden.'],alternativ:'Ähnlicher Sprachstil könnte eher Folge als Ursache von Sympathie sein.'},
 C:{aussagen:[S('C','Ähnlicher Gebrauch von Funktionswörtern sagte gegenseitiges Interesse und Beziehungsstabilität voraus. Die Daten sind korrelativ.',['ireland11'],'transfer'),S('B','Hohe kognitive Belastung behindert Verstehen und Lernen.',['sweller88'],'transfer'),S('B','Finanzwissen ist in der Bevölkerung ungleich verteilt und oft gering.',['lusardi14'],'beleg'),S('D','Kundenbegriffe aufgreifen und eigene Fachbegriffe erklären ist eine bewährte Praxisregel.',[],'heuristik')],widerspruch:'Keine Studie zeigt, dass gezielte Sprachstilangleichung in Beratungen wirkt.',transfer:'Befunde zur Verständlichkeit sind gut übertragbar. Befunde zur Sympathie durch Sprachstil kaum.'},
 D:{wann:'Durchgehend, besonders beim Erklären von Produkten, Zahlen und Bedingungen.',ziel:'Verständlich sein, ohne zu vereinfachen.',schritte:['Hören, welche Begriffe der Kunde nutzt.','Diese Begriffe übernehmen.','Fachbegriffe nur mit Erklärung.','Ein Gedanke pro Satz.','Verständnis prüfen.'],formulierungen:['„Sie sprechen von Ihrer Betriebsrente. Meinen Sie die Direktversicherung über den Arbeitgeber?“','„Eigenanteil heißt hier: das, was Sie nach der Zahlung der Pflegekasse selbst tragen.“'],reaktion:['Kunde nutzt Fachbegriffe sicher: Tempo und Tiefe erhöhen.'],pruefen:'Kunde stellt passende Rückfragen.',anpassen:'Bei Fachleuten Fachsprache zulassen.'},
 E:{gut:'„Die Kasse zahlt einen festen Zuschuss. Was darüber liegt, zahlen Sie selbst. Ein Zusatztarif kann einen Teil davon übernehmen.“',schlecht:'„Das läuft über Festzuschüsse nach § 55 SGB V mit Bonusstaffel.“',dialog:[['K','Was ist denn diese Dynamik?'],['B','Gute Frage. Dynamik heißt: Der Beitrag und die Leistung steigen regelmäßig ein Stück, damit die Absicherung mit den Preisen mitwächst. Sie können dem jeweils widersprechen.']],analyse:'Kurze, konkrete Erklärung mit der wichtigen Einschränkung (Widerspruchsmöglichkeit).',alternative:'Erst fragen, was der Kunde darüber schon weiß.',finanz:'„Rendite“ durch „was das Geld im Jahr bringt“ ersetzen, wenn der Kunde unsicher wirkt.',allgemein:'IT-Support: „Das Programm ist abgestürzt“ statt „Prozess wurde terminiert“.'},
 F:{nicht:['Bei Fachkunden, die präzise Begriffe erwarten.'],manipulativ:'Wenn Vereinfachung wichtige Einschränkungen weglässt.',missverstaendnisse:['Einfach heißt nicht unvollständig.'],ethik:'Kosten, Grenzen und Risiken bleiben in einfacher Sprache erhalten.',nichtAbleiten:'Dass Kopieren des Sprechstils Vertrauen erzeugt.'},
 G:{uebungen:[{level:'Einsteiger',titel:'Fachwort-Liste',aufgabe:'Schreibe zehn Fachbegriffe aus deinem Alltag mit je einer Erklärung in einem Satz.'},{level:'Fortgeschritten',titel:'Zwei Niveaus',aufgabe:'Erkläre die Beitragsrückgewähr einmal einem Laien und einmal einer Steuerberaterin.'}],selbsttest:[{f:'Was ist sinnvolle sprachliche Anpassung?',a:['Den Dialekt des Kunden übernehmen','Die Begriffe des Kunden aufgreifen und Fachwörter erklären','Möglichst viele Fachwörter zeigen'],r:1,e:'Anpassung an das Verständnis, nicht an den Stil.'}],reflexion:['Welche Fachwörter nutze ich, ohne es zu merken?'],kriterien:['Kundenbegriffe genutzt','Fachwörter erklärt','Einschränkungen genannt']},
 uebung:[{sit:'Kunde fragt nach dem Unterschied zwischen Pflegetagegeld und Pflegerente.',kunde:'Das klingt doch alles gleich. Was ist denn jetzt der Unterschied?',ziel:'Verständlich und korrekt erklären, ohne Tarifdetails zu erfinden.'}],q:['ireland11','sweller88','lusardi14']});

T({id:'t-spiegelgrenzen',titel:'Wann Spiegeltechniken nicht funktionieren',bereich:'zuhoeren',eltern:'t-spiegeln',stufe:'C',kn:['e7','b13'],verkn:['t-spiegeln','t-nonverbal','t-emotion'],
 schnell:{kern:['Mechanisches Nachahmen wirkt unnatürlich und kann als Taktik erkannt werden.','Falsch gedeutete Gefühle beschädigen Vertrauen.','Nicht jede Pause muss gefüllt werden.','Ein kurzes „Ja“ ist keine Zustimmung.','Körperhaltung erlaubt keine Aussage über Sympathie oder Kaufbereitschaft.','Kultur und Persönlichkeit verändern, was angemessen wirkt.'],satz:'„Ich bin nicht sicher, ob ich Sie richtig verstanden habe. Wie meinen Sie das genau?“',vermeiden:['Jeden Satz spiegeln','Schweigen als Zustimmung werten']},
 A:{def:'Diese Einheit sammelt Situationen, in denen Spiegeln keine Hilfe ist oder schadet, und zeigt, woran man das erkennt.',herkunft:'Ergebnisse aus Mimikry-, Reaktanz- und Persuasionsforschung.',begriffe:[['Persuasionswissen','Wissen von Konsumenten über Beeinflussungstaktiken.'],['Reaktanz','Gegenwehr bei wahrgenommener Einschränkung der Freiheit.']],theorie:'Wenn Menschen eine Technik erkennen, deuten sie das Gespräch als Beeinflussungsversuch (Friestad und Wright 1994).',abgrenzung:'Es geht nicht darum, Spiegeln zu vermeiden, sondern es dosiert und ehrlich einzusetzen.'},
 B:{text:['Mechanisches Nachahmen wird als Absicht erkannt und stört die Natürlichkeit.','Eine falsche Gefühlsdeutung zeigt, dass man nicht verstanden hat.','Pausen geben Denkzeit. Wer sie füllt, nimmt dem Kunden die Gelegenheit, Wichtiges zu sagen.','Kurze Bestätigungen („ja“, „mhm“) bedeuten oft nur „ich höre“.'],alternativ:'In manchen Kulturen gelten Blickkontakt oder Nähe anders. Allgemeine Regeln passen nicht für alle.'},
 C:{aussagen:[S('B','Starke Nachahmung senkte Sympathie und Vertrauen.',['wessler24'],'beleg'),S('C','Nachahmung erhöhte in einer präregistrierten Studie Vertrauen nicht.',['hale16'],'beleg'),S('B','Wahrgenommene Freiheitsbedrohung führt zu Ärger und abwehrenden Gedanken.',['rains13'],'beleg'),S('B','Konsumenten nutzen Wissen über Taktiken, um Beeinflussungsversuche abzuwehren.',['friestad94'],'beleg')],widerspruch:'—',transfer:'Allgemeine Befunde, nicht spezifisch für Versicherungsgespräche.'},
 D:{wann:'Bei jedem Spiegeln mitdenken.',ziel:'Erkennen, wann Spiegeln schadet.',schritte:['Signale beachten: „Sag ich doch“, Ungeduld, Kürze.','Spiegeln reduzieren, mehr fragen.','Bei Unsicherheit nachfragen statt deuten.','Pausen aushalten.'],formulierungen:['„Ich wiederhole mich vielleicht. Sagen Sie mir einfach, wenn ich etwas falsch verstanden habe.“','„Ich nehme mal Ihr Ja als ‚verstanden‘. Wie sehen Sie das inhaltlich?“'],reaktion:['Kunde genervt: zur Sache, kürzer.'],pruefen:'Gespräch fließt wieder.',anpassen:'Weniger Technik, mehr Inhalt.'},
 E:{gut:'Kunde: „Ja.“ Berater: „Ist das ein Ja, passt so, oder eher ein Ja, ich höre zu?“ Kunde: „Eher Letzteres, ich muss nachdenken.“',schlecht:'Berater deutet jedes „Ja“ als Zustimmung und geht zur Unterschrift über.',
  dialog:[['K','Mir ist das zu viel heute.'],['B','Sie sind gerade überfordert und brauchen etwas Ruhe?'],['K','Nein, überfordert bin ich nicht. Ich will nur nicht heute unterschreiben.'],['B','Verstanden, dann entscheiden Sie in Ruhe. Was brauchen Sie bis dahin von mir?']],
  analyse:'Die Gefühlsdeutung („überfordert“) war falsch. Der Berater korrigiert sich sofort und folgt dem eigentlichen Anliegen.',alternative:'Von Anfang an nur den Inhalt spiegeln: „Heute keine Entscheidung.“',finanz:'Weitere Beispiele: „Sie sind skeptisch.“ (Kunde: „Nein, ich bin nur vorsichtig.“) besser: „Sie möchten vorsichtig vorgehen.“',allgemein:'Kundin im Möbelhaus lehnt sich zurück. Verkäufer kopiert die Haltung, Kundin bemerkt es und wirkt irritiert.'},
 F:{nicht:['Siehe alle Punkte oben.'],manipulativ:'Ja-Ketten über Spiegelfragen.',missverstaendnisse:['„Mhm“ ist keine Zustimmung.','Ähnliche Haltung ist kein Kaufsignal.'],ethik:'Spiegeln nie, um Zustimmung zu konstruieren.',nichtAbleiten:'Allgemeingültige Regeln für Blickkontakt oder Nähe.'},
 G:{uebungen:[{level:'Fortgeschritten',titel:'Fehlerjagd',aufgabe:'Lies die Beispielsammlung und markiere, was du selbst schon so gemacht hast.'}],selbsttest:[{f:'Kunde sagt nach deiner Zusammenfassung „Mhm“. Was tust du?',a:['Zum Abschluss gehen','Nachfragen, wie er es inhaltlich sieht','Lauter wiederholen'],r:1,e:'„Mhm“ heißt oft nur „ich höre zu“.'}],reflexion:['Welche meiner Gesprächsgewohnheiten könnte als Technik erkannt werden?'],kriterien:['Bestätigung nicht als Zustimmung gewertet','Falsche Deutung sofort korrigiert']},
 sammlung:[
  ['Ich habe schon eine Pflegeversicherung über die Arbeit.','Sie sind schon abgesichert und sehen keinen Bedarf.','Unterstellt fehlenden Bedarf.','Sie haben bereits etwas über die Arbeit. Wissen Sie, was darin enthalten ist, oder wäre ein Blick in die Unterlagen hilfreich?'],
  ['Das ist mir alles zu kompliziert.','Sie sind überfordert.','Wertet und dramatisiert.','Ich habe es zu kompliziert erklärt. Welcher Teil ist am wenigsten klar?'],
  ['Mein Schwager macht das.','Sie vertrauen mir nicht.','Unterstellt Misstrauen.','Ihr Schwager kümmert sich darum. Möchten Sie heute trotzdem etwas Bestimmtes klären?'],
  ['Ich muss sparen, die Kinder studieren.','Sie haben kein Geld.','Zu weitgehend, abwertend.','Die Ausbildung der Kinder hat gerade Vorrang. Wollen wir schauen, was in der Zeit ohne zusätzliche Kosten wichtig ist?'],
  ['Wir überlegen, ob wir das Haus verkaufen.','Sie brauchen also keine Gebäudeversicherung mehr.','Zieht vorschnelle Schlüsse.','Der Verkauf ist noch offen. Was hängt für Sie an dieser Entscheidung?'],
  ['(schweigt nach einer Frage)','„Also ich meine damit …“ (füllt sofort)','Nimmt Denkzeit.','Pause aushalten, dann: „Lassen Sie sich Zeit.“'],
  ['Ja, ja.','„Gut, dann machen wir das so.“','Wertet Bestätigung als Zustimmung.','Ist das ein Ja zum Vorschlag oder ein „ich höre zu“?'],
  ['Meine Frau entscheidet das.','Sie wollen sich drücken.','Unterstellt Ausrede.','Ihre Frau entscheidet mit. Was wäre ihr wichtig, und wollen wir zu dritt sprechen?']
 ],
 uebung:[{sit:'Kunde sagt nur „Ja, ja“ nach deiner Erklärung.',kunde:'Ja, ja.',ziel:'Klären, ob das Zustimmung oder nur Zuhören bedeutet, ohne Druck.'}],q:['wessler24','hale16','rains13','friestad94']});
